import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
def task_func():
    class JSONPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, body_dict):
            body_bytes = json.dumps(body_dict).encode('utf-8')
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body_bytes)))
            self.end_headers()
            self.wfile.write(body_bytes)

        def do_POST(self):
            content_type = self.headers.get('Content-Type', '')
            if content_type != 'application/json':
                self._send_response(400, {'status': 'error', 'message': 'Content-Type header is not application/json'})
                return
            length_header = self.headers.get('Content-Length')
            try:
                content_length = int(length_header) if length_header is not None else 0
            except ValueError:
                content_length = 0
            body = self.rfile.read(content_length)
            try:
                data = json.loads(body.decode('utf-8') if body else '{}')
            except json.JSONDecodeError:
                self._send_response(400, {'status': 'error', 'message': 'Invalid JSON'})
                return
            if 'data' not in data:
                self._send_response(400, {'status': 'error', 'message': 'No data key in request'})
                return
            self._send_response(200, SUCCESS_RESPONSE)
    return JSONPostHandler

