    'message': 'Invalid data received.'
}
def task_func():
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('content-type', '')
            if content_type.split(';')[0].strip().lower() != 'application/json':
                self.send_error_response('Content-Type header is not application/json')
                return
            content_length = self.headers.get('content-length')
            try:
                length = int(content_length) if content_length is not None else 0
            except ValueError:
                length = 0
            body = self.rfile.read(length) if length > 0 else b''
            try:
                data = json.loads(body.decode('utf-8') or '{}')
            except json.JSONDecodeError:
                self.send_error_response('Invalid JSON')
                return
            if 'data' not in data:
                self.send_error_response('No data key in request')
                return
