import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json
def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, code, body):
            if isinstance(body, dict):
                body_bytes = json.dumps(body).encode('utf-8')
                content_type = 'application/json'
            else:
                body_bytes = str(body).encode('utf-8')
                content_type = 'text/plain; charset=utf-8'
            self.send_response(code)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(len(body_bytes)))
            self.end_headers()
            self.wfile.write(body_bytes)
        def do_POST(self):
            try:
                form = cgi.FieldStorage(fp=self.rfile, headers=self.headers, environ={'REQUEST_METHOD': 'POST', 'CONTENT_TYPE': self.headers.get('Content-Type')})
                if 'email' in form:
                    raw_data = form.getvalue('email')
                else:
                    length = int(self.headers.get('Content-Length', 0))
                    raw_data = self.rfile.read(length).decode('utf-8')
                try:
                    data = json.loads(raw_data)
                except json.JSONDecodeError as e:
                    raise json.JSONDecodeError(e.msg, e.doc, e.pos)
                required_keys = ['subject', 'message', 'to']
                if not all(k in data for k in required_keys):
                    raise ValueError('Missing required email fields')
                subject = data['subject']
                message = data['message']
                to_addr = data['to']
                msg = MIMEText(message)
                msg['Subject'] = subject
                msg['From'] = smtp_username
                msg['To'] = to_addr
                try:
                    server = smtplib.SMTP(smtp_server, smtp_port)
                    server.starttls()
                    server.login(smtp_username, smtp_password)
                    server.sendmail(smtp_username, [to_addr], msg.as_string())
                    server.quit()
                except smtplib.SMTPAuthenticationError as e:
                    self._send_response(535, {'error': 'Authentication Failed'})
                    raise e
                self._send_response(200, {'status': 'Email sent successfully'})
            except json.JSONDecodeError:
                self._send_response(400, {'error': 'Invalid JSON'})
            except ValueError as e:
                self._send_response(400, {'error': str(e)})
            except smtplib.SMTPAuthenticationError:
                pass
            except Exception as e:
                self._send_response(500, {'error': 'Internal Server Error'})
    return EmailRequestHandler

import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.isfile(file_path):
        raise ValueError("File does not exist")

    with open(file_path, "r") as f:
