from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def is_email(s):
        return bool(re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", s))

    def process_value(v, counts):
        if v is None:
            return None
        if isinstance(v, dict):
            new_dict = {}
            for k, val in v.items():
                processed = process_value(val, counts)
                if processed is not None:
                    new_dict[k] = processed
            return new_dict
        if isinstance(v, list):
            new_list = []
            for item in v:
                processed = process_value(item, counts)
                if processed is not None:
                    new_list.append(processed)
            return new_list
        if isinstance(v, str):
            if is_email(v):
                v = REPLACE_NONE
            counts[v] += 1
            return v
        if isinstance(v, (int, float, bool)):
            counts[v] += 1
            return v
        return v

    obj = json.loads(json_str)
    value_counts = Counter()
    processed_data = process_value(obj, value_counts)
    return {"data": processed_data, "value_counts": value_counts}

