        if not isinstance(country, str):
            raise ValueError("Country names must be strings")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = int(math.floor(population))
        countries.append(country)
        populations.append(population_int)

    df = pd.DataFrame({"Country": countries, "Population": populations})

    output_path = os.path.join(output_dir, file_name)
    abs_output_path = os.path.abspath(output_path)

    try:
        os.makedirs(os.path.dirname(abs_output_path), exist_ok=True)
        df.to_csv(abs_output_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")

    return abs_output_path, df

