    current = obj
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key not found in path: {key}")

    def collect_numbers(x):
        nums = []
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            nums.append(x)
        elif isinstance(x, list):
            for item in x:
                nums.extend(collect_numbers(item))
        elif isinstance(x, dict):
            for v in x.values():
                nums.extend(collect_numbers(v))
        return nums

    values = collect_numbers(current)
    if not values:
        raise ValueError("No numeric data found")

    df = pd.DataFrame({"value": values})
    if df.empty:
        raise ValueError("Data is empty or corrupted")

    fig, ax = plt.subplots()
    sns.boxplot(data=df, x="value", ax=ax)
    ax.set_title("Boxplot of Extracted Numeric Data")
    return fig

import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("Input JSON data is empty or not a string")
    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError("Malformed JSON data") from e
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")
    countries = []
    populations = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item in JSON data must be a dictionary")
        country = item.get("Country")
        population = item.get("Population")
        if not isinstance(country, str) or not country.strip():
            raise ValueError("Country names must be non-empty strings")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population_int = math.floor(population)
        countries.append(country)
        populations.append(population_int)
    df = pd.DataFrame({"Country": countries, "Population": populations})
    if not os.path.isdir(output_dir):
        raise IOError("Output directory does not exist")
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError("Failed to write CSV file") from e
    return file_path, df

